  VALUES ?en { "dimethyl ether"@en "propanal"@en "isobutane"@en "fructose"@en "lactose"@en
               "ammonium cyanate"@en "methyl formate"@en }
  ?item rdfs:label ?en ;
        wdt:P274 ?formula .
  OPTIONAL { ?item rdfs:label ?sv . FILTER(LANG(?sv) = "sv") }
}

SELECT ?item ?en ?sv ?formula ?cid WHERE {
  VALUES ?en { "isocitric acid"@en "caffeic acid"@en }
