SELECT ?lexeme ?lemma ?sense ?item WHERE {
  VALUES ?lemma { "glycerol"@sv "etylen"@sv "ASA"@sv "väteklorid"@sv "saltsyra"@sv "vätesulfid"@sv "bikarbonat"@sv "isocitronsyra"@sv }
  ?lexeme dct:language wd:Q9027 ;
          wikibase:lemma ?lemma .
  OPTIONAL { ?lexeme ontolex:sense ?sense . OPTIONAL { ?sense wdt:P5137 ?item } }
}
